// Package render lays a package's conversions out as one Go source file — the
// file head, one toInnerModel func per conversion, one statement per field.
package render

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/s12chung/ccbox/tools/toinnermodel-gen/pkg/pair"
	"github.com/s12chung/ccbox/tools/toinnermodel-gen/pkg/source"
)

// fileHeader marks the file as generated, so lint skips it
const fileHeader = "// Code generated by toinnermodel-gen; DO NOT EDIT."

// File lays the package's conversions out as one generated file — the marked
// structs' funcs first, then each structType reached through them, each once
type File struct {
	pkg   string
	funcs []Func
}

// NewFile lays pairs' conversions out as one file, each struct once
func NewFile(pkg string, pairs []pair.Pair) File {
	uniqSet := uniqPairSet{seen: map[string]bool{}}
	for _, p := range pairs {
		uniqSet.add(p)
	}

	f := File{pkg: pkg}
	for _, p := range uniqSet.pairs {
		f.funcs = append(f.funcs, NewFunc(p))
	}
	return f
}

// uniqPairSet accumulates the pairs to render, each struct's once
type uniqPairSet struct {
	pairs []pair.Pair
	seen  map[string]bool
}

// add lays p's Pair down, then its structTypes', in reach order
func (s *uniqPairSet) add(p pair.Pair) {
	if s.seen[p.Marked.Name] {
		return
	}
	s.seen[p.Marked.Name] = true
	s.pairs = append(s.pairs, p)
	for _, fieldPair := range p.Fields {
		if st, ok := fieldPair.(pair.StructType); ok && st.Pair != nil {
			s.add(*st.Pair)
		}
	}
}

// Bytes lays the file out as its Go source
func (f File) Bytes() []byte {
	b := &bytes.Buffer{}
	fmt.Fprintf(b, "%s\n\npackage %s\n\n", fileHeader, f.pkg)
	for _, fn := range f.funcs {
		b.Write(fn.Bytes())
	}
	return b.Bytes()
}

// Func lays one conversion out as its toInnerModel method
type Func struct {
	input      string
	innerModel string
	statements []statement
}

// NewFunc lays p's conversion out, one statement per field
func NewFunc(p pair.Pair) Func {
	fn := Func{input: p.Marked.Name, innerModel: p.InnerModel.Name}
	for _, fieldPair := range p.Fields {
		fn.statements = append(fn.statements, newStatement(fieldPair))
	}
	return fn
}

// Bytes lays the func out as its Go source
func (f Func) Bytes() []byte {
	b := &bytes.Buffer{}
	fmt.Fprintf(b, "func (x *%s) toInnerModel() %s {\n\tvar out %s\n", f.input, f.innerModel, f.innerModel)
	for _, s := range f.statements {
		s.write(b)
	}
	b.WriteString("\treturn out\n}\n\n")
	return b.Bytes()
}

// statement is one field's conversion laid out
type statement interface {
	write(b *bytes.Buffer)
}

func newStatement(fieldPair pair.FieldPair) statement {
	switch pair := fieldPair.(type) {
	case pair.Assign:
		return assign{pair.Field}
	case pair.Deref:
		return deref{pair.Field}
	case pair.Convert:
		return convert{pair.Field, pair.Fn}
	case pair.StructType:
		return structType{pair.Field, pair.TwinType}
	default:
		panic(fmt.Sprintf("render: unknown field pairing %T", fieldPair))
	}
}

// assign moves a same-shape field across
type assign struct{ field source.Field }

func (s assign) write(b *bytes.Buffer) {
	fmt.Fprintf(b, "\tout.%s = x.%s\n", s.field.Name, s.field.Name)
}

// deref derefs an input pointer onto its value target, nil-guarded
type deref struct{ field source.Field }

func (s deref) write(b *bytes.Buffer) {
	fmt.Fprintf(b, "\tif x.%s != nil {\n\t\tout.%s = *x.%s\n\t}\n", s.field.Name, s.field.Name, s.field.Name)
}

// convert passes an input field through the marker-named package func
type convert struct {
	field source.Field
	fn    string
}

func (s convert) write(b *bytes.Buffer) {
	fmt.Fprintf(b, "\tout.%s = %s(x.%s)\n", s.field.Name, s.fn, s.field.Name)
}

// structType converts a struct field — pointer or value — via its toInnerModel;
// only the pointer nil-guards, and a pointer target takes the conversion's address
type structType struct {
	field    source.Field
	twinType string
}

func (s structType) write(b *bytes.Buffer) {
	if !strings.HasPrefix(s.field.Type, "*") {
		fmt.Fprintf(b, "\tout.%s = x.%s.toInnerModel()\n", s.field.Name, s.field.Name)
		return
	}
	if strings.HasPrefix(s.twinType, "*") {
		target := loweredTarget(s.field.Name)
		fmt.Fprintf(b, "\tif x.%s != nil {\n\t\t%s := x.%s.toInnerModel()\n\t\tout.%s = &%s\n\t}\n",
			s.field.Name, target, s.field.Name, s.field.Name, target)
		return
	}
	fmt.Fprintf(b, "\tif x.%s != nil {\n\t\tout.%s = x.%s.toInnerModel()\n\t}\n", s.field.Name, s.field.Name, s.field.Name)
}

// loweredTarget names the pointer target's local: the field name with its leading
// uppercase run lowered — VNC -> vnc, DefaultVariant -> defaultVariant
func loweredTarget(name string) string {
	upper := 0
	for upper < len(name) && 'A' <= name[upper] && name[upper] <= 'Z' {
		upper++
	}
	return strings.ToLower(name[:upper]) + name[upper:]
}
